import { test, expect } from '@playwright/test';

test.describe('Sticky Footer Navigation on Mobile', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com'); // Replace with the actual URL
    await page.setViewportSize({ width: 375, height: 812 }); // Mobile viewport
  });

  test('should display sticky footer navigation', async ({ page }) => {
    const footer = page.getByRole('contentinfo');
    await expect(footer).toBeVisible();
    await expect(footer).toHaveCSS('position', 'fixed');
    await expect(footer).toHaveCSS('bottom', '0px');
  });

  test('should remain visible when scrolling', async ({ page }) => {
    await page.mouse.wheel(0, 500); // Scroll down
    const footer = page.getByRole('contentinfo');
    await expect(footer).toBeVisible();
    await expect(footer).toHaveCSS('position', 'fixed');
  });
});
